"""Disposition rates by window and stratum, and re-disposition against the conformance reference.

`inspection_results.disposition` is written at inspection time from the reading the measuring machine
produced, against the drawing tolerance in `drawing_limits`. These helpers count it back out.

The drawing states its tolerance against the conformance reference of QP-07 §3: the deviation a reading
traceable to GB-100.000 would give, free of instrument offset. An instrument's offset is established by the
retained-artefact programme (QP-07 §5), not from certificate figures (QP-07 §4 note). An offset can only
change when the machine's compensation table is written to (`PERIODIC+ADJUST`), so each machine's history is
split at those events and the offset in each segment is taken from the artefact rounds inside it.
"""
import sqlite3
from statistics import mean, stdev


PRE_WINDOW = (13, 18)
POST_WINDOW = (19, 24)

# An artefact-derived offset is applied only where it is distinguishable from zero: |offset| greater than
# twice its standard error (taken over per-artefact means) combined with the artefacts' certified
# uncertainty.
COVERAGE_K = 2.0
# Readings are recorded to 0.01 um; corrected readings and offsets are held at the same resolution.
RESOLUTION_DP = 2


def connect(db_path):
    con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    return con


def tolerance_um(con):
    row = con.execute(
        "SELECT tol_um FROM drawing_limits WHERE part_number='MAN-4471' AND feature='BORE_DIA_42'"
    ).fetchone()
    return float(row["tol_um"])


def parts(con, window):
    lo, hi = window
    return con.execute(
        "SELECT r.*, h.family AS heat_family FROM inspection_results r "
        "JOIN heats h ON h.heat_id = r.heat_id WHERE r.week BETWEEN ? AND ? ORDER BY r.part_id",
        (lo, hi),
    ).fetchall()


def nonconforming_rate_pct(rows, key="disposition"):
    if not rows:
        return None
    bad = sum(1 for r in rows if r[key] == "FAIL")
    return 100.0 * bad / len(rows)


def strata_rates_pct(rows, column):
    by = {}
    for r in rows:
        by.setdefault(str(r[column]), []).append(r)
    return {k: round(nonconforming_rate_pct(v), 2) for k, v in sorted(by.items())}


# --- conformance reference (QP-07 §3, §5) ------------------------------------------------------------

def _segments(con, machine_id):
    """Date intervals [start, end) between compensation writes on a machine."""
    writes = [
        r["event_date"]
        for r in con.execute(
            "SELECT event_date FROM calibration_events WHERE machine_id=? AND event_type LIKE '%ADJUST%' "
            "ORDER BY event_date",
            (machine_id,),
        )
    ]
    bounds = [""] + writes + ["9999-12-31"]
    return list(zip(bounds[:-1], bounds[1:]))


def _artefact_offset(con, machine_id, start, end):
    """Mean (reading - certified) over the artefact rounds in [start, end), with its expanded uncertainty."""
    rows = con.execute(
        "SELECT m.artefact_id, AVG(m.measured_um - p.certified_um) AS dev, MAX(p.uncertainty_um) AS u "
        "FROM reference_measurements m JOIN reference_parts p ON p.artefact_id = m.artefact_id "
        "WHERE m.machine_id=? AND m.measured_on >= ? AND m.measured_on < ? GROUP BY m.artefact_id",
        (machine_id, start, end),
    ).fetchall()
    if len(rows) < 2:
        return None
    devs = [r["dev"] for r in rows]
    se = stdev(devs) / len(devs) ** 0.5
    u_cert = max(r["u"] for r in rows)
    return {
        "offset_um": mean(devs),
        "expanded_u_um": COVERAGE_K * (se * se + u_cert * u_cert) ** 0.5,
        "artefacts": len(devs),
    }


def machine_offsets(con):
    """Per machine, a list of segments {start, end, offset_um, applied_um, ...}."""
    out = {}
    machines = [r[0] for r in con.execute("SELECT DISTINCT machine_id FROM inspection_results ORDER BY 1")]
    for m in machines:
        segs = []
        for start, end in _segments(con, m):
            est = _artefact_offset(con, m, start, end)
            if est is None:
                raise RuntimeError(
                    f"{m}: no retained-artefact verification between {start or 'start'} and {end}; "
                    "QP-07 §5 requires one after every compensation write"
                )
            significant = abs(est["offset_um"]) > est["expanded_u_um"]
            applied = round(est["offset_um"], RESOLUTION_DP) if significant else 0.0
            segs.append({"start": start, "end": end, **est, "applied_um": applied})
        out[m] = segs
    return out


def offset_for(offsets, machine_id, inspected_on):
    for s in offsets[machine_id]:
        if s["start"] <= inspected_on < s["end"]:
            return s["applied_um"]
    raise KeyError((machine_id, inspected_on))


def redisposition(rows, offsets, tol_um):
    """Readings brought to the conformance reference and dispositioned against the drawing tolerance."""
    out = []
    for r in rows:
        off = offset_for(offsets, r["machine_id"], r["inspected_on"])
        ref_um = round(r["measured_um"] - off, RESOLUTION_DP)
        out.append({
            **dict(r),
            "offset_um": off,
            "reference_um": ref_um,
            "disposition_reference": "PASS" if abs(ref_um) <= tol_um else "FAIL",
        })
    return out


def window_offset_um(rows):
    """Per machine, the offset applied to its readings over a window (part-weighted)."""
    by = {}
    for r in rows:
        by.setdefault(r["machine_id"], []).append(r["offset_um"])
    return {m: round(mean(v), RESOLUTION_DP) + 0.0 for m, v in sorted(by.items())}

